/* ==UserStyle==
@name Planet Minecraft Catppuccin
@namespace github.com/catppuccin/userstyles/styles/planet-minecraft
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/planet-minecraft
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/planet-minecraft/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aplanet-minecraft
@description Soothing pastel theme for Planet Minecraft
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("planetminecraft.com") {
  [data-theme="light"] {
    #catppuccin(@lightFlavor);
  }
  [data-theme="dark"] {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --body-bg: @crust;
    --header-bg: @base;
    --content-bg: @surface0;
    --container-bg: @base;
    --menu-bg: @surface0;
    --menu-color: @subtext1;
    --menu-selected-bg: @surface1;
    --menu-selected-color: @accent;
    --footer-bg: @mantle;
    --bg-navbar: @mantle;
    --tab-selected: @accent;
    --input-bg: @surface0;
    --dark-mid-bg: @base;
    --title-color: @text;
    --text-color: @text;
    --text-color-medium: @subtext0;
    --text-color-light: @subtext1;
    --border-color: @base;
    --footer-a-color: @accent;
    --nav-hover: @accent;
    --stat-color: @red;
    --a-color: @accent;
    --a-hover: @accent;
    --a-selected: fade(@accent, 80%);
    --tab-hover: fade(@accent, 80%);
    --tab-color: @subtext0;
    --nav-color: @text;
    --widget-wrap-bg: @mantle;
    --shine-start: @surface2;
    --shine-end: @surface1;
    --widget-bg: @surface0;
    --light-bg: @surface0;
    --medium-bg: @crust;
    --toolbar-bg: @surface0;
    --shine-highlight: @surface0;
    --border-color-light: @surface0;
    --site-border-color: @surface0;
    --graphic-bg: @surface0;
    --notice-bg: @overlay0;
    --notice-color: @text;
    --menu-disabled-color: @crust;
    --control-bg: @accent;
    --a-visited: @accent;
    --nav-bar-border: none;
    --feed-alt-bg: @surface1;
    --nav-selected: @accent;

    .tab_options > ul > li.currentpage,
    .tab_options > ul > li.ui-state-active,
    .tab_options > ul > li:hover {
      border-bottom-color: @accent;
    }

    .site_btn_secondary {
      color: @subtext1;
      background: @surface1;
      &:hover {
        color: @accent;
        background: fade(@surface1, 80%);
      }
    }

    .site_btn,
    .site_btn_alt,
    #subscribe_full .site_btn,
    .pagination p a.pagination_page,
    .pagination p > span.pagination_page,
    .vert_menu > ul > li:only-child > a.current_select,
    .vert_menu > ul > li > a.current_select {
      color: @base;
      background: @accent;
      &:not(:disabled, [data-disabled="disabled"]):hover {
        background: fade(@accent, 80%);
      }
    }

    #profile-bar #profile-actions .togglable.selected {
      background: @accent;
      color: @base;
    }

    .tipso_bubble .bottom {
      background: @surface0 !important;
    }

    /* because the icons on the display mode buttons are white, we cant have white base here, so we improvise for latte */
    & when (@flavor = latte) {
      #display_modes a {
        background: @text !important;
        box-shadow: none !important;
      }

      /* fix nav menu dropdown icons */
      .navbar_icon .dropdown {
        --svozk: var(--s) -256px -326px !important;
        background: var(--s) -256px -326px !important;
      }

      .content-actions li {
        background: @surface0;

        a,
        .link,
        .js_link,
        .js_link_m {
          color: @text;
        }
      }

      .content-actions li .js_link:hover,
      .content-actions li .js_link_m:hover,
      .content-actions li .link:hover,
      .content-actions li a:hover {
        .material-icons {
          color: @text !important;
        }

        color: @text !important;
        background: @accent !important;
      }

      .content-actions li .material-icons {
        color: @subtext0 !important;
      }
    }

    & when not(@flavor = latte) {
      #display_modes a {
        background: @base !important;
        box-shadow: none !important;
      }
    }

    #display_modes a.selected,
    #display_modes a:hover {
      background: @accent;
    }

    .navigation-wrap .navmenu a {
      text-shadow: none !important;
    }

    #header
      #header-wrap
      .header_text
      > ul
      > li
      > .material-btn.mem_submit
      .material-icons,
    #header #header-wrap .header_text > ul > li > a.mem_submit .material-icons,
    #mobileRightPanel
      .sidr-inner
      > ul
      > li
      > .material-btn.mem_submit
      .material-icons,
    #mobileRightPanel .sidr-inner > ul > li > a.mem_submit .material-icons {
      color: @green !important;
    }

    #header
      #header-wrap
      .header_text
      > ul
      > li
      > .material-btn[data-alert="1"].mem_notifications
      .material-icons,
    #header
      #header-wrap
      .header_text
      > ul
      > li
      > .material-btn[data-alert="1"].mem_tickets
      .material-icons,
    #header
      #header-wrap
      .header_text
      > ul
      > li
      > a[data-alert="1"].mem_notifications
      .material-icons,
    #header
      #header-wrap
      .header_text
      > ul
      > li
      > a[data-alert="1"].mem_tickets
      .material-icons,
    #mobileRightPanel
      .sidr-inner
      > ul
      > li
      > .material-btn[data-alert="1"].mem_notifications
      .material-icons,
    #mobileRightPanel
      .sidr-inner
      > ul
      > li
      > .material-btn[data-alert="1"].mem_tickets
      .material-icons,
    #mobileRightPanel
      .sidr-inner
      > ul
      > li
      > a[data-alert="1"].mem_notifications
      .material-icons,
    #mobileRightPanel
      .sidr-inner
      > ul
      > li
      > a[data-alert="1"].mem_tickets
      .material-icons {
      color: @yellow;
    }

    .material-icons,
    .mem_submit > span,
    .mem_notifications > span {
      color: @text !important;
    }

    .green {
      background: @green;
      color: @base;

      .material-icons {
        color: @base;
      }
    }

    // .content-actions li:not(:only-child, :first-child) {
    //   border-top: none;
    // }

    .tipso_content,
    .member_profile_card_right {
      background: @surface0;
    }

    .tipso_arrow {
      border-color: @surface0;
    }

    #popular-reel .caption {
      & when (@flavor = latte) {
        background: fade(@text, 50%) !important;

        .pop-title {
          color: @base !important;
          text-shadow: none;
        }

        .caption-subtitle {
          color: @crust !important;
          text-shadow: none;
        }
      }

      & when not(@flavor = latte) {
        background: fade(@base, 50%) !important;

        .pop-title {
          color: @text !important;
          text-shadow: none;
        }

        .caption-subtitle {
          color: @subtext0 !important;
          text-shadow: none;
        }

        .content-actions li {
          background: @surface0;

          a,
          .link,
          .js_link,
          .js_link_m {
            color: @text;
          }
        }

        .content-actions li .js_link:hover,
        .content-actions li .js_link_m:hover,
        .content-actions li .link:hover,
        .content-actions li a:hover {
          .material-icons {
            color: @accent !important;
          }
          color: @accent !important;
          background: @surface1 !important;
        }

        .content-actions li .material-icons {
          color: @subtext0 !important;
        }
      }
    }

    #content_notice .site_btn,
    #content_notice .site_btn_alt {
      text-shadow: none;
    }

    .custom_input:focus,
    input:focus,
    select:focus,
    textarea:focus {
      border-color: @accent;
    }
  }
}

